48: const MATERIAL_PRICES_ID = "1-2n4Q2XYjGyRqoogAnS_Id1tGzUBq2bKHvHVKeXEYXM"; // 2_Material_Prices_and_Freight_Matrix.gsheet
49: const CUSTOMER_POS_ID = "1FfkSYTCxUFYj3dE6VHAOWEqDa4MVU3yMz7rwjefh-Ig"; // 4_Customer_POs_and_Delivery_Plans.gsheet
