52: // ===================== 2. ENTRY POINTS =====================
53: 
54: function doGet() {
55:   return json_({ ok: true, service: 'PSC WDB LINE to Sheets gateway', version: 2 });
56: }
57: 
58: function doPost(e) {
59:   const receivedAt = new Date();
60:   let body = {};
61: 
62:   try {
63:     body = parseBody_(e);
64: 
65:     // 1. ตรวจจับคำสั่งส่งตรงจาก LINE Messaging API Webhook
66:     if (body.events) {
67:       // 1.1 ถ้าเป็นการกดปุ่ม Verify จาก LINE Console (events ว่าง)
68:       if (!body.events || body.events.length === 0) {
69:         return json_({ ok: true, status: 'verified' });
70:       }
71: 
72:       // 1.2 วนลูปประมวลผลข้อความจริงจาก LINE (ทั้งข้อความตัวอักษรและรูปภาพ PO)
73:       for (let i = 0; i < body.events.length; i++) {
74:         const ev = body.events[i];
75:         if (ev.type === 'message') {
76:           if (ev.message && ev.message.type === 'text') {
77:             handleLineDirectEvent_(ev, receivedAt);
78:           } else if (ev.message && ev.message.type === 'image') {
79:             handleLineImageEvent_(ev, receivedAt);
80:           }
81:         }
82:       }
83:       return json_({ ok: true, processed: body.events.length });
84:     }
85: 
86:     // 2. ตรวจจับคำสั่งส่งผ่าน Relay / Backend Sync เดิม (ต้องใช้ PSC_SYNC_TOKEN)
87:     const payload = body.payload || {};
88:     const reportId = String(payload.reportId || '');
89:     const syncJobId = String(payload.syncJobId || '');
90:     const messageId = String(payload.messageId || '');
91: 
92:     if (!isAuthorized_(e, body)) {
93:       auditBestEffort_([receivedAt, 'unauthorized', reportId, syncJobId, messageId, 'Invalid or missing PSC_SYNC_TOKEN']);
94:       return json_({ ok: false, error: 'unauthorized' });
95:     }
96: 
97:     if (body.event !== 'line_report' || !body.payload) {
98:       auditBestEffort_([receivedAt, 'rejected', reportId, syncJobId, messageId, 'event must be line_report and payload is required']);
99:       return json_({ ok: false, error: 'invalid_payload' });
100:     }
