605: function callGeminiApi_(promptText, imagePart, apiKey) {
606:   const url = "https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=" + apiKey;
607:   const parts = [{ text: promptText }];
608:   if (imagePart) {
609:     parts.push({ inlineData: { mimeType: imagePart.mimeType, data: imagePart.base64Data } });
610:   }
611: 
612:   const payload = {
613:     contents: [{ parts: parts }],
614:     generationConfig: { responseMimeType: "application/json" }
615:   };
616: 
617:   try {
618:     const res = UrlFetchApp.fetch(url, {
619:       method: "post",
620:       contentType: "application/json",
621:       payload: JSON.stringify(payload),
622:       muteHttpExceptions: true
623:     });
624: 
625:     if (res.getResponseCode() === 200) {
